import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

class Leaderboard {
    private Map<Integer, Integer> scores;
    private TreeMap<Integer, Integer> scoreCounts;

    public Leaderboard() {
        scores = new HashMap<>();
        scoreCounts = new TreeMap<>(Collections.reverseOrder());
    }

    public void addScore(int playerId, int score) {
        int oldScore = scores.getOrDefault(playerId, 0);
        if (oldScore > 0) {
            changeCount(oldScore, -1);
        }
        int newScore = oldScore + score;
        scores.put(playerId, newScore);
        changeCount(newScore, 1);
    }

    public int top(int K) {
        int sum = 0;
        int remaining = K;
        for (Map.Entry<Integer, Integer> entry : scoreCounts.entrySet()) {
            int take = Math.min(remaining, entry.getValue());
            sum += entry.getKey() * take;
            remaining -= take;
            if (remaining == 0) {
                break;
            }
        }
        return sum;
    }

    public void reset(int playerId) {
        int oldScore = scores.remove(playerId);
        changeCount(oldScore, -1);
    }

    private void changeCount(int score, int delta) {
        int next = scoreCounts.getOrDefault(score, 0) + delta;
        if (next == 0) {
            scoreCounts.remove(score);
        } else {
            scoreCounts.put(score, next);
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Leaderboard {
    private Map<Integer, Integer> scores;

    public Leaderboard() {
        scores = new HashMap<>();
    }

    public void addScore(int playerId, int score) {
        scores.put(playerId, scores.getOrDefault(playerId, 0) + score);
    }

    public int top(int K) {
        List<Integer> values = new ArrayList<>(scores.values());
        values.sort(Collections.reverseOrder());
        int sum = 0;
        for (int i = 0; i < K; i++) {
            sum += values.get(i);
        }
        return sum;
    }

    public void reset(int playerId) {
        scores.remove(playerId);
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

class Leaderboard {
    private Map<Integer, Integer> scores;

    public Leaderboard() {
        scores = new HashMap<>();
    }

    public void addScore(int playerId, int score) {
        scores.put(playerId, scores.getOrDefault(playerId, 0) + score);
    }

    public int top(int K) {
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        for (int score : scores.values()) {
            heap.offer(score);
            if (heap.size() > K) {
                heap.poll();
            }
        }
        int sum = 0;
        for (int score : heap) {
            sum += score;
        }
        return sum;
    }

    public void reset(int playerId) {
        scores.remove(playerId);
    }
}

import java.util.HashMap;
import java.util.Map;

class Leaderboard {
    private static final int MAX_SCORE = 100000;
    private Map<Integer, Integer> scores;
    private int[] scoreCounts;

    public Leaderboard() {
        scores = new HashMap<>();
        scoreCounts = new int[MAX_SCORE + 1];
    }

    public void addScore(int playerId, int score) {
        int oldScore = scores.getOrDefault(playerId, 0);
        if (oldScore > 0) {
            scoreCounts[oldScore]--;
        }
        int newScore = oldScore + score;
        scores.put(playerId, newScore);
        scoreCounts[newScore]++;
    }

    public int top(int K) {
        int sum = 0;
        int remaining = K;
        for (int score = MAX_SCORE; score >= 0 && remaining > 0; score--) {
            int take = Math.min(remaining, scoreCounts[score]);
            sum += score * take;
            remaining -= take;
        }
        return sum;
    }

    public void reset(int playerId) {
        int oldScore = scores.remove(playerId);
        scoreCounts[oldScore]--;
    }
}

import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import java.util.TreeSet;

class Leaderboard {
    private Map<Integer, PlayerScore> records;
    private TreeSet<PlayerScore> ranking;

    public Leaderboard() {
        records = new HashMap<>();
        ranking = new TreeSet<>((a, b) -> {
            if (a.score != b.score) {
                return Integer.compare(b.score, a.score);
            }
            return Integer.compare(a.playerId, b.playerId);
        });
    }

    public void addScore(int playerId, int score) {
        PlayerScore old = records.get(playerId);
        int newScore = score;
        if (old != null) {
            ranking.remove(old);
            newScore += old.score;
        }
        PlayerScore updated = new PlayerScore(playerId, newScore);
        records.put(playerId, updated);
        ranking.add(updated);
    }

    public int top(int K) {
        int sum = 0;
        Iterator<PlayerScore> iterator = ranking.iterator();
        for (int count = 0; count < K; count++) {
            sum += iterator.next().score;
        }
        return sum;
    }

    public void reset(int playerId) {
        PlayerScore old = records.remove(playerId);
        ranking.remove(old);
    }

    private static class PlayerScore {
        final int playerId;
        final int score;

        PlayerScore(int playerId, int score) {
            this.playerId = playerId;
            this.score = score;
        }
    }
}
